  ". นี่เป็นยอดสะสม ไม่ใช่จำนวนครั้งต่อข้อความ ระบบติดตามข้อมูลส่วนใหญ่ใช้คำตอบแชตปกติ; Scene Tracker, Diary และคำเชิญ Party/Guild ใช้ข้อมูลในคำตอบหลัก ไม่เรียก AI เพิ่ม หากข้อมูลขาดจะแสดงเท่าที่ได้รับ Manual Sync, เจน NPC และคำสั่งจาก UI ก็อาจใช้คำขอ": 1026,
  ". This is a cumulative total, not requests per message. Scene tracking, diaries and invitations use the main reply without extra AI calls. Missing data stays incomplete. Manual sync, NPC generation and UI actions may make requests.": 1026,
  " ยอดนี้เป็นยอดสะสม ไม่ใช่จำนวนต่อข้อความ ฉาก ไดอารี และคำเชิญใช้คำตอบหลักโดยไม่เรียก AI เพิ่ม หากข้อมูลขาดจะแสดงเท่าที่ได้รับ การซิงก์เอง สร้างตัวละคร และคำสั่งจากหน้าจออาจใช้คำขอเพิ่ม": 1026,
  "How automatic UI updates work": 1027,
  "การอัปเดตหน้าจออัตโนมัติทำงานอย่างไร": 1027,
  "After your first reply, the extension adds the current structured state and short patch rules to the normal role-play prompt.": 1028,
  "หลังคำตอบแรกของผู้เล่น ส่วนเสริมจะแนบข้อมูลปัจจุบันและกฎอัปเดตสั้น ๆ ในคำสั่งโรลเพลย์ปกติ": 1028,
  "The character produces its normal reply once. If a confirmed fact changed, it appends an invisible state patch to that same reply.": 1029,
  "ตัวละครสร้างคำตอบปกติครั้งเดียว หากข้อเท็จจริงเปลี่ยนจะแนบชุดอัปเดตที่ซ่อนไว้ในคำตอบนั้น": 1029,
  "The extension removes the patch from view, validates every operation against a strict allowlist, saves it to this chat, and redraws the relevant tabs.": 1030,
  "ส่วนเสริมซ่อนชุดอัปเดต ตรวจคำสั่งตามรายการที่อนุญาต บันทึกในแชตและแสดงแท็บที่เกี่ยวข้องใหม่": 1030,
  "If no patch is returned, the activity capsule says “No state changes.” This means tracking ran successfully but had nothing confirmed to save.": 1031,
  "If no patch is returned, the activity capsule says “No state changes.” Tracking ran successfully but had nothing confirmed to save.": 1031,
